class Solution {
public:
    int findValidSplit(std::vector<int>& nums) {
        int n = nums.size();
        std::unordered_map<int, int> last_idx;
        for (int i = 0; i < n; ++i) {
            int x = nums[i];
            for (int d = 2; d * d <= x; ++d) {
                if (x % d == 0) {
                    last_idx[d] = i;
                    while (x % d == 0) x /= d;
                }
            }
            if (x > 1) last_idx[x] = i;
        }
        int max_reach = 0;
        for (int i = 0; i < n - 1; ++i) {
            int x = nums[i];
            for (int d = 2; d * d <= x; ++d) {
                if (x % d == 0) {
                    max_reach = std::max(max_reach, last_idx[d]);
                    while (x % d == 0) x /= d;
                }
            }
            if (x > 1) max_reach = std::max(max_reach, last_idx[x]);
            if (max_reach <= i) return i;
        }
        return -1;
    }
};

class Solution {
    public int findValidSplit(int[] nums) {
        int n = nums.length;
        java.util.Map<Integer, Integer> lastIdx = new java.util.HashMap<>();
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            for (int d = 2; d * d <= x; d++) {
                if (x % d == 0) {
                    lastIdx.put(d, i);
                    while (x % d == 0) x /= d;
                }
            }
            if (x > 1) lastIdx.put(x, i);
        }
        int maxReach = 0;
        for (int i = 0; i < n - 1; i++) {
            int x = nums[i];
            for (int d = 2; d * d <= x; d++) {
                if (x % d == 0) {
                    maxReach = Math.max(maxReach, lastIdx.get(d));
                    while (x % d == 0) x /= d;
                }
            }
            if (x > 1) maxReach = Math.max(maxReach, lastIdx.get(x));
            if (maxReach <= i) return i;
        }
        return -1;
    }
}

var findValidSplit = function(nums) {
    const n = nums.length;
    const lastIdx = new Map();
    for (let i = 0; i < n; i++) {
        let x = nums[i];
        for (let d = 2; d * d <= x; d++) {
            if (x % d === 0) {
                lastIdx.set(d, i);
                while (x % d === 0) x = Math.floor(x / d);
            }
        }
        if (x > 1) lastIdx.set(x, i);
    }
    let maxReach = 0;
    for (let i = 0; i < n - 1; i++) {
        let x = nums[i];
        for (let d = 2; d * d <= x; d++) {
            if (x % d === 0) {
                maxReach = Math.max(maxReach, lastIdx.get(d));
                while (x % d === 0) x = Math.floor(x / d);
            }
        }
        if (x > 1) maxReach = Math.max(maxReach, lastIdx.get(x));
        if (maxReach <= i) return i;
    }
    return -1;
};
